insert into public.tpl_market_zonas(
  region_codigo,comuna,zona,microzona,nombre_normalizado,
  fuente_definicion,confianza,activo,metadata
)
select distinct
  p.region_codigo,
  p.comuna,
  p.zona_texto,
  null,
  public.tpl_market_normalizar_texto_v1(p.zona_texto),
  'market_ingesta',
  70,
  true,
  jsonb_build_object('origen','zona_texto_propiedad')
from public.tpl_market_propiedades p
where coalesce(trim(p.comuna),'')<>''
  and coalesce(trim(p.zona_texto),'')<>''
on conflict(comuna,nombre_normalizado) do update set
  activo=true,
  updated_at=now();

update public.tpl_market_propiedades p
set zona_id=z.id,
    updated_at=now()
from public.tpl_market_zonas z
where p.zona_id is null
  and public.tpl_market_normalizar_texto_v1(p.comuna)
      = public.tpl_market_normalizar_texto_v1(z.comuna)
  and public.tpl_market_normalizar_texto_v1(p.zona_texto)
      = z.nombre_normalizado;

